import{z as t,x as r,o as B,c as p,q as o,j as s,D as a,d as n,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"住房：资产与消费","description":"","frontmatter":{"title":"住房：资产与消费","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/housing-asset-consumption.md","filePath":"econ/housing-asset-consumption.md","lastUpdated":1791063341000}'),d={name:"econ/housing-asset-consumption.md"};function C(c,E,m,h,u,F){const A=r("Mermaid");return B(),p("div",null,[E[2]||(E[2]=o('<h1 id="住房-资产与消费" tabindex="-1">住房：资产与消费 <a class="header-anchor" href="#住房-资产与消费" aria-label="Permalink to &quot;住房：资产与消费&quot;">​</a></h1><div class="epigraph"><p>同一套房子同时是消费品和资产负债表上最大的一项资产；把租金服务与资产需求拆开，组合问题才变得可写。</p><footer>—— Henderson and Ioannides, A Model of Housing Tenure Choice, AER 1983；对照 Flavin and Yamashita, 2002；Campbell and Cocco, 2003, 2007</footer></div><p><a href="/econ/annuity-puzzle">上一课</a>把住房点成劣质年金。本课缺口是正式拆开：住房服务进入期内效用，房屋净值进入跨期预算，租买选择把两者焊在同一决策里。不重写 Yaari 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准 LCH/PIH 的 \\(c\\) 是可分消费品。住房不是：住在里面才有服务流，卖掉才有残值，交易成本高，杠杆（按揭）把利率与违约写进家庭欧拉。Henderson 与 Ioannides（1983）把租买写成投资需求与消费需求是否相等：投资需求大于消费需求则持有投资性住房，反之则租。Flavin 与 Yamashita（2002）强调：年轻房主的组合被住房净值主导，股票份额被挤出——这是下一课参与之谜的实物侧。Campbell 与 Cocco（2003, 2007）把按揭类型与房价风险、劳动收入风险放在一起：房价与收入若正相关，住房是坏对冲。</p><p>缺口是给家庭金融加上不可分、高成本的住房，而不是重写一般均衡商品空间。</p><p><span class="marginnote">Sinai 与 Souleles：租客暴露在租金风险里，自住对冲「住在这城里」的成本。住房作为对冲的符号取决于人是否计划长期住下去。</span></p><p><span class="marginnote">术语翻译：「住房服务」不是中介费，而是「住这套房」每期产生的效用流——面积、位置、采光折算成的隐形租金。自住等于向自己交租：服务流进效用函数，房子本身进资产负债表，同一套房子挂两本账。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>效用 \\(u(c,h)\\)，\\(h\\) 为住房服务；自住时 \\(h\\) 与房屋存量绑在一起，租住时 \\(h\\) 在租赁市场买。资产方程含按揭余额、房价随机、交易与搬家成本。租买是离散选择；一旦自住，组合在住房上过度暴露，其他风险资产的最优份额下降。本课不估计房价过程，不把城市经济学写进来。</p>',10)),(B(),s(l,null,{default:a(()=>[i(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANN%5B%22%E5%B9%B4%E9%87%91%E4%B9%8B%E8%B0%9C%3A%20%E4%BD%8F%E6%88%BF%E5%85%85%E5%BD%93%E5%8A%A3%E8%B4%A8%E5%B9%B4%E9%87%91%22%5D%20--%3E%20SPLIT%5B%22%E6%8B%86%3A%20%E6%9C%8D%E5%8A%A1%E6%B5%81%20vs%20%E5%87%80%E5%80%BC%22%5D%0A%20%20SPLIT%20--%3E%20TENURE%5B%22%E7%A7%9F%E4%B9%B0%3A%20%E6%8A%95%E8%B5%84%E9%9C%80%E6%B1%82%E5%AF%B9%E6%B6%88%E8%B4%B9%E9%9C%80%E6%B1%82%22%5D%0A%20%20TENURE%20--%3E%20PORT%5B%22%E5%87%80%E5%80%BC%E4%B8%BB%E5%AF%BC%3A%20%E6%8C%A4%E5%87%BA%E8%82%A1%E7%A5%A8%22%5D%0A%20%20TENURE%20--%3E%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%E7%A7%9F%E9%87%91%E6%88%96%E6%94%BE%E5%A4%A7%E6%94%B6%E5%85%A5%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"价格 \\(p\\) 仍是资产价格，不是盘口中间价。本补层不进入限价簿。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"机制是捆绑。消费需求决定要多少平方；投资需求决定要持有多少房屋作为资产。两者只在无摩擦时能用租赁拆开。摩擦使许多家庭被迫同时满足两个需求，于是出现「过度住房、过少股票」。按揭把无风险利率换成浮动或固定的名义合同，通胀与再融资进入家庭金融，仍不是微观结构课。",-1)),(B(),s(l,null,{default:a(()=>[i(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20D1%5B%22%E6%B6%88%E8%B4%B9%E9%9C%80%E6%B1%82%EF%BC%9A%E6%83%B3%E4%BD%8F%E5%A4%9A%E5%A4%A7%22%5D%20--%3E%20FR%7B%22%E7%A7%9F%E8%B5%81%E5%B8%82%E5%9C%BA%E8%83%BD%E5%90%A6%E6%97%A0%E6%91%A9%E6%93%A6%E6%8B%86%E5%BC%80%EF%BC%9F%22%7D%0A%20%20D2%5B%22%E6%8A%95%E8%B5%84%E9%9C%80%E6%B1%82%EF%BC%9A%E6%83%B3%E6%8C%81%E5%A4%9A%E5%B0%91%E6%88%BF%E4%BA%A7%22%5D%20--%3E%20FR%0A%20%20FR%20--%3E%7C%22%E8%83%BD%EF%BC%9A%E4%BA%A4%E6%98%93%E6%97%A0%E6%88%90%E6%9C%AC%22%7C%20OK%5B%22%E7%A7%9F%E5%88%B0%E5%90%88%E9%80%82%E9%9D%A2%E7%A7%AF%EF%BC%8C%E8%B5%84%E4%BA%A7%E5%8D%95%E7%8B%AC%E9%85%8D%E7%BD%AE%22%5D%0A%20%20FR%20--%3E%7C%22%E4%B8%8D%E8%83%BD%EF%BC%9A%E6%88%90%E6%9C%AC%E9%AB%98%E4%B8%94%E4%B8%8D%E5%8F%AF%E5%88%86%22%7C%20B%5B%22%E8%A2%AB%E8%BF%AB%E7%94%A8%E5%90%8C%E4%B8%80%E5%A5%97%E6%88%BF%E6%BB%A1%E8%B6%B3%E4%B8%A4%E4%B8%AA%E9%9C%80%E6%B1%82%22%5D%0A%20%20B%20--%3E%20OH%5B%22%E6%88%BF%E5%AD%90%E6%AF%94%E6%8A%95%E8%B5%84%E9%9C%80%E8%A6%81%E7%9A%84%E5%A4%A7%EF%BC%9A%E8%BF%87%E5%BA%A6%E4%BD%8F%E6%88%BF%22%5D%0A%20%20B%20--%3E%20OS%5B%22%E5%87%80%E5%80%BC%E9%94%81%E6%AD%BB%E5%9C%A8%E6%88%BF%E5%AD%90%E9%87%8C%EF%BC%9A%E8%BF%87%E5%B0%91%E8%82%A1%E7%A5%A8%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=o('<p><span class="marginnote">数字实例：一个家庭理想的居住面积对应 60 万的房，理想的房产投资只有 20 万。当地最小像样的两居却要 90 平、首付 60 万——两本账被一套房焊死：住房超额、股票挤出。若租赁市场厚，本可以租小一点的房、把差额投进金融资产。</span></p><p>与遗赠：住房不可分且交易成本高，强化终点留下房产而非金融年金。与承诺：首付与提前还贷罚则可当金蛋。本课只标明接口。</p><p>期内效用仍是<a href="/econ/preference-choice">偏好</a>上的 \\(u(c,h)\\)，不重写完备传递。跨期预算多了房价随机与按揭合同，欧拉对金融资产仍成立，对住房可能因不可分与成本变成离散选择。Campbell–Cocco 强调：浮动利率把通胀与短期利率写进还款，固定利率把再融资期权写进合同——都是家庭金融，不是期限结构主干的再推导。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>商业地产、REIT、住房抵押贷款证券化是另一组市场，量化栏与机构金融会碰，本课家庭侧停在自住与按揭。也不把 2008 年危机写成住房课的正文——那是宏观金融附录，不是租买理论。</p><p><span class="marginnote">常见误区：初学者容易把「自住」当成纯消费、把「买房」当成纯投资。Henderson–Ioannides 的要点是二者被同一套房子捆绑：自住也是在持有一笔高度集中的资产头寸，「住得舒服」和「押注房价」在账本上是同一笔钱。</span></p><p>后课默认：家庭组合在住房占净值很高的现实约束下展开；参与之谜不能假装有一个无住房的 Merton 问题。</p><p>租买把住房服务需求与资产需求焊在同一决策；摩擦下无法用租赁完全拆开。</p><p>净值主导挤出股票，是参与之谜的实物侧，不是另写一套 CAPM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>住房同时是 \\(h\\) 与资产，租买把两个需求焊在一起。</li><li>净值主导挤出股票；房价–收入相关决定对冲还是放大。</li><li>不重写年金公式，不写簿；只补家庭资产负债表的最大一项。</li><li>房价与劳动收入相关决定对冲还是放大。</li><li>首付可当承诺，房产可当劣质年金。</li><li>出处：Henderson and Ioannides, <em>AER</em> 1983；Flavin and Yamashita 2002；Campbell and Cocco, 2003, 2007。</li></ul>',11))])}const T=t(d,[["render",C]]);export{f as __pageData,T as default};
